<?php

// Standalone instructions: recipients need the exported files, not access to this bot.
trait EternalGuidesUi
{
    public function uiClientGuide(string $client, string $mode = 'auto'): string
    {
        $exit = $mode === 'exit';
        $group = $exit ? 'Eternal · WARP-выход' : 'Eternal · Авто';
        $nodes = $exit ? 'Eternal-Exit-WARP-Nodes.txt' : 'Eternal-Nodes.txt';
        $prefix = $exit ? 'Eternal WARP ·' : 'Eternal ·';
        $folder = $exit ? 'Eternal — выход через WARP' : 'Подключения Eternal';
        $ip = filter_var((string) ($this->ip ?? ''), FILTER_VALIDATE_IP, FILTER_FLAG_IPV4);
        $expected = $exit ? '<code>warp=on</code> — сайты видят выход Cloudflare.'
            : ($ip ? '<code>ip=' . htmlspecialchars($ip, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . '</code> — это выход Eternal.'
                : 'адрес выхода Eternal, который может подтвердить отправитель настроек.');
        $test = "\n\n<b>🔎 Проверка</b>\nС включённым подключением открой <a href=\"https://1.1.1.1/cdn-cgi/trace\">страницу проверки</a> в браузере. Ожидается $expected Проверку Wi-Fi и LTE делай отдельно.";
        $share = "\n\nЕсли не помогло, пришли отправителю текст ошибки и укажи сеть: Wi-Fi или LTE. Файлы содержат ключи доступа — передавай их только тому, кому даёшь VPN.";
        $heading = "Режим: <b>$group</b>\n" . ($exit ? 'Телефон или компьютер → Eternal → Cloudflare. Отдельное приложение WARP не требуется.'
            : 'Соединение выходит в интернет через Eternal; в файле есть прямые входы и резерв.');

        if ($client === 'lxbox') {
            $file = $exit ? 'Eternal-Exit-WARP-Android.json' : 'Eternal-Auto-Android.json';
            return "Для подключения нужен файл: <code>$file</code>. Получи его вместе с этой инструкцией.\n\n"
                . "<b>📱 LxBox · Android</b>\n$heading\n\n"
                . "<b>1. Установи приложение</b>\n<a href=\"https://play.google.com/store/apps/details?id=com.leadaxe.lxbox\">LxBox в Google Play</a> → «Установить». Если магазин недоступен, <a href=\"https://github.com/Leadaxe/LxBox/releases/latest\">APK от разработчика</a>: скачай .apk, открой и разреши установку из этого источника.\n\n"
                . "<b>2. Сохрани и импортируй</b>\nВ Telegram у файла нажми ⋮ → «Сохранить в загрузки». В LxBox открой ☰ → «Настройки приложения» → «Общие» → «Резервное копирование» (в прежних версиях пункт сразу в ☰). В верхнем разделе «Импорт» нажми «Выбрать файл…», выбери JSON и «Объединить с текущими». Подтверди импорт. Если предложен перезапуск — выполни его и открой приложение снова.\n\n"
                . "<b>3. Подключись</b>\nНа главной нажми ▶ справа от «$group». Если VPN ещё выключен, нажми Start и разреши Android создать VPN-подключение.\n\n"
                . "<b>Если видна только папка</b>\n☰ → «Серверы» → «$folder» → + → «Добавить авто-узел…». Включи в него только узлы этой папки, сохрани и выбери новый авто-узел на главной. Обычное «Авто» может выбирать другие серверы."
                . $test . "\n\n<b>Если нет интернета</b>\nВыключи другой VPN, переподключись и подожди минуту. Для проверки выбери в этой папке «Резерв по IP 1», а если его нет — «Резерв по имени». При ошибке «Некорректная резервная копия» проверь имя JSON и импортируй его именно в верхнем разделе «Импорт», а не «Перенос на Desktop»." . $share;
        }
        if ($client === 'exclave') {
            return "Для подключения нужен файл: <code>$nodes</code>. Получи его вместе с этой инструкцией.\n\n"
                . "<b>📱 Exclave · Android</b>\n$heading\n\n"
                . "<b>1. Установи приложение</b>\nОткрой <a href=\"https://github.com/ExclaveNetwork/Exclave/releases/latest\">релиз разработчика</a> → Assets. Для обычного современного телефона скачай APK с <code>arm64-v8a</code> без <code>legacy</code>. Открой APK и разреши установку из этого источника.\n\n"
                . "<b>2. Добавь узлы</b>\nВ Telegram у TXT: ⋮ → «Сохранить в загрузки». В Exclave: + («Добавить профиль») → «Импорт из файла» → выбери TXT. Должны появиться узлы «$prefix …». Если файл не находится: открой TXT, скопируй весь текст → + → «Импорт из буфера обмена».\n\n"
                . "<b>3. Создай авто-переключение</b>\n+ → «Ручные настройки» → «Балансировщик». Имя: <code>$group</code>. Тип: «Список». Добавь только узлы из этого TXT. Стратегия: <code>leastPing</code>. Пользовательский URL проверки: <code>https://1.1.1.1/cdn-cgi/trace</code>. Интервал: <code>60</code> секунд. Сохрани кнопкой ✓.\n\n"
                . "<b>4. Включи VPN</b>\nНажми созданный балансировщик, затем кнопку подключения. Разреши Android создать VPN-подключение. В настройке «Сервисный режим» должен быть выбран VPN, если раньше использовался режим «Только прокси»."
                . $test . "\n\n<b>Если нет интернета</b>\nОстанови другой VPN и переподключись. Для проверки выбери «$prefix Резерв по IP 1» (если его нет — «$prefix Резерв по имени») и подключись. Если он работает, проверь участников балансировщика и подожди минуту. Узлы из другого набора в него не добавляй." . $share;
        }
        if ($client === 'shadowrocket') {
            $conf = $exit ? 'Eternal-Exit-WARP-Shadowrocket.conf' : 'Eternal-Auto-Shadowrocket.conf';
            return "Для подключения нужны оба файла: <code>$nodes</code> и <code>$conf</code>. Получи их вместе с этой инструкцией.\n\n"
                . "<b>🍎 Shadowrocket · iPhone / iPad</b>\n$heading\n\n"
                . "<b>1. Установи приложение</b>\n<a href=\"https://apps.apple.com/app/shadowrocket/id932747118\">Shadowrocket в App Store</a>. Приложение платное; если уже установлено, обнови его.\n\n"
                . "<b>2. Добавь узлы из TXT</b>\nОткрой полученный TXT, выдели и скопируй весь текст. Открой Shadowrocket и подтверди добавление. Если приглашения нет, на главной нажми «Вставить» под «Проверкой соединения». Разреши чтение буфера обмена. Появятся узлы «$prefix …»; имена не меняй.\n\n"
                . "<b>3. Добавь правила из .conf</b>\nВ Telegram открой файл .conf → «Поделиться» → «Сохранить в Файлы». В Shadowrocket: «Конфигурация» → «Импорт из облака» → выбери этот файл в сохранённой папке. Нажми на импортированную конфигурацию → «Использовать конфигурацию».\n\n"
                . "<b>4. Включи подключение</b>\nНа главной: «Глобальная маршрутизация» → «Конфигурация». Включи переключатель подключения. На запрос iOS о добавлении VPN нажми «Разрешить» и подтверди кодом устройства. Правило в .conf выбирает группу «$group» автоматически."
                . $test . "\n\n<b>Если нет интернета</b>\nУбедись, что импортированы оба файла одного режима. Выбери «$prefix Резерв по IP 1» (если его нет — «$prefix Резерв по имени»), временно поставь «Глобальная маршрутизация → Прокси» и переподключись. Если заработало, верни «Конфигурация» и проверь, что используется нужный .conf." . $share;
        }
        if ($client === 'v2rayn') {
            $file = $exit ? 'Eternal-Exit-WARP-v2rayN.txt' : 'Eternal-Auto-v2rayN.txt';
            return "Для подключения нужен файл: <code>$file</code>. Получи его вместе с этой инструкцией.\n\n"
                . "<b>💻 v2rayN · Windows 10 / 11</b>\n$heading\nНазвание набора не включает автовыбор: TXT добавляет отдельные узлы, нужный выбираешь сам.\n\n"
                . "<b>1. Установи приложение</b>\nОткрой <a href=\"https://github.com/2dust/v2rayN/releases/latest\">релиз разработчика</a> → Assets. Для ПК с Intel/AMD скачай <code>v2rayN-windows-64.zip</code>. Полностью распакуй ZIP в отдельную папку и запусти <code>v2rayN.exe</code> из неё.\n\n"
                . "<b>2. Импортируй TXT</b>\nСкачай TXT из Telegram и открой в Блокноте. Ctrl+A → Ctrl+C. В главном окне v2rayN нажми Ctrl+V (вне поля ввода) или «Серверы → Импорт ссылок общего доступа из буфера обмена». Появятся узлы Eternal.\n\n"
                . "<b>3. Выбери подключение</b>\nВыдели «$prefix Резерв по IP 1» и нажми Enter или правую кнопку мыши → «Сделать активным». Если его нет или он не подключается, попробуй «$prefix Резерв по IP 2», затем «$prefix Прямой gRPC». Выбирай только узлы из полученного TXT. Снизу: «Системный прокси → Установить системный прокси». В «Маршрутизация» выбери правило с <code>(Global)</code> в имени. Если изменение не применилось, нажми «Перезапустить службу».\n\n"
                . "<b>4. Для остальных приложений</b>\nСистемный прокси работает с приложениями, которые его используют. Для трафика остальных: «Перезапустить от имени администратора», подтверди запрос Windows и включи «Включить TUN»."
                . $test . "\n\n<b>Если нет интернета</b>\nПроверь активный узел и системный прокси, отключи другой VPN. Для остановки выбери «Очистить системный прокси» и выключи TUN, если включал его. Если браузер работает, а отдельное приложение нет — проверь TUN." . $share;
        }
        if ($client === 'karing_android' || $client === 'karing_ios') {
            $ios = $client === 'karing_ios';
            $file = $exit ? 'Eternal-Exit-WARP-Karing.txt' : 'Eternal-Auto-Karing.txt';
            $platform = $ios ? '🍎 Karing · iPhone / iPad' : '📱 Karing · Android';
            $install = $ios
                ? '<a href="https://apps.apple.com/app/karing/id6472431552">Karing в App Store</a> → «Загрузить». Если уже установлен, обнови приложение.'
                : '<a href="https://github.com/KaringX/karing/releases/latest">Релиз Karing от разработчика</a> → Assets. Для обычного современного телефона скачай APK с <code>android_arm64-v8a</code>. Открой APK и разреши установку из этого источника.';
            $save = $ios ? 'В Telegram открой TXT → «Поделиться» → «Сохранить в Файлы».'
                : 'В Telegram у TXT: ⋮ → «Сохранить в загрузки».';
            return "Для подключения нужен файл: <code>$file</code>. Получи его вместе с этой инструкцией.\n\n"
                . "<b>$platform</b>\n$heading\nTXT добавляет список узлов; автоматическую группу не создаёт.\n\n"
                . "<b>1. Установи приложение</b>\n$install\n\n"
                . "<b>2. Импортируй файл</b>\n$save В Karing: + («Добавить профиль») → «Импорт файла конфигурации» → «Выбрать файл» → этот TXT. В поле «Примечание» укажи <code>$group</code> и нажми ✓ («Сохранить») справа вверху. Если файл не находится, скопируй весь его текст и используй «Импорт из буфера обмена».\n\n"
                . "<b>3. Выбери сервер</b>\nНа главной нажми имя сервера → «Выбор сервера». В импортированном профиле выбери «$prefix Резерв по IP 1». Если его нет или он не работает, попробуй «$prefix Резерв по IP 2», затем «$prefix Прямой gRPC». Выбирай только узлы полученного файла. Глобальный автовыбор может захватить другие профили.\n\n"
                . "<b>4. Подключись</b>\nНа главной переключи «Правила» на «Глобально» — для первой проверки весь трафик пойдёт через выбранный узел. Включи переключатель подключения. Прими системный запрос на создание VPN-подключения."
                . $test . "\n\n<b>Если нет интернета</b>\nОстанови другой VPN и переподключись. Проверь выбранный узел и его принадлежность нужному профилю. Если TXT не импортируется, обнови Karing и повтори импорт из файла или полного содержимого буфера." . $share;
        }
        return 'Для этого приложения инструкция пока недоступна. Попроси отправителя указать, каким клиентом открывать присланный файл.';
    }
}
